ia(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}.field{display:flex;flex-direction:column;gap:6px;margin-bottom:13px}.field label{font-size:.9rem;font-weight:650}.field input,.field select,.field textarea{width:100%;padding:11px 12px;border-radius:8px;border:1px solid #353e50;background:#0e1118;color:var(--ink);font:inherit}.field textarea{min-height:100px}.card{padding:17px;border:1px solid var(--line);border-radius:12px;background:#11151e}.card h3{margin:0 0 8px}.price{font-size:1.2rem;font-weight:800;color:var(--gold)}.notice{background:#f5a62312;border:1px solid #8a611d;border-radius:9px;padding:12px;margin:12px 0}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#202635} @media(max-width:760px){.top{align-items:center;flex-wrap:wrap}.top .nav{width:100%;justify-content:flex-start;flex-wrap:wrap;margin-left:0}.top .nav .btn{flex:0 1 auto}}@media(max-width:600px){.grid{grid-template-columns:1fr}.panel{padding:14px}.top{align-items:flex-start}.top .nav{gap:6px}.nav .btn{flex:1}}
