<section class="panel active" id="explorar"><h2>Encuentra el servicio adecuado</h2><p class="muted">Busca por nombre del servicio, contador o especialidad. Los servicios rechazados se muestran informativamente y no se pueden contratar.</p><div class="grid"><div class="field"><label for="busqueda">Buscar</label><input id="busqueda" placeholder="Ej. declaración de renta, nómina…"></div><div class="field"><label for="especialidad">Especialidad</label><select id="especialidad"><option value="">Todas</option><?php foreach(['Impuestos y DIAN','Contabilidad general','Nómina y seguridad social','Auditoría','Facturación electrónica','Finanzas empresariales'] as $e): ?><option><?php echo cc_srv_h($e); ?></option><?php endforeach; ?></select></div></div><div class="grid" id="servicios-lista"><?php foreach(($data['servicios']??[]) as $v): ?><article class="card servicio" data-search="<?php echo cc_srv_h(mb_strtolower(($v['titulo']??'').' '.($v['especialidad']??'').' '.($v['contador_nombre']??'').' '.($v['contador_apellido']??''),'UTF-8')); ?>"><h3><?php echo cc_srv_h($v['titulo']); ?></h3><p class="muted"><?php echo cc_srv_h(($v['contador_nombre']??'').' '.($v['contador_apellido']??'')); ?> · <?php echo cc_srv_h($v['especialidad']); ?></p><p><?php echo nl2br(cc_srv_h($v['descripcion'])); ?></p><p class="muted">Matrícula: <?php echo cc_srv_h($v['matricula_profesional']??'No indicada'); ?> · Experiencia: <?php echo (int)($v['experiencia_anos']??0); ?> años</p><p class="price">$<?php echo number_format((float)$v['precio'],0,',','.'); ?> COP</p><?php if(($v['estado']??'')==='rechazado'): ?><div class="notice" style="border-color:#b83a46;background:#b83a4615;color:#ffb8bf"><strong>Servicio rechazado por la administración</strong><br>Este servicio ya no está disponible para nuevas contrataciones.</div><?php else: ?><form method="post" action="<?php echo URLROOT.'/marketplace/contratar/'.(int)$v['id']; ?>" onsubmit="return confirm('Continuarás a los métodos de pago digitales para contratar este servicio. ¿Deseas continuar?')"><button class="btn">Contratar y pagar</button></form><?php endif; ?></article><?php endforeach; ?><?php if(empty($data['servicios'])): ?><p class="notice">Todavía no hay servicios publicados y aprobados.</p><?php endif; ?></div></section>
