"><option value="">No configurar</option><option value="Daviplata">Daviplata</option></select><div class="field"><label>Cuenta / número / instrucciones</label><input name="datos_pago[]" maxlength="255" placeholder="Número o instrucciones de pago"></div><div class="field"><label>Titular de la cuenta (opcional)</label><input name="titular_pago[]" maxlength="180" placeholder="Nombre del titular"></div></div><div class="card"><label>Bancolombia</label><select name="metodo_pago[]"><option value="">No configurar</option><option value="Bancolombia">Bancolombia</option></select><div class="field"><label>Cuenta / número / instrucciones</label><input name="datos_pago[]" maxlength="255" placeholder="Número o instrucciones de pago"></div><div class="field"><label>Titular de la cuenta (opcional)</label><input name="titular_pago[]" maxlength="180" placeholder="Nombre del titular"></div></div><div class="card"><label>Efecty</label><select name="metodo_pago[]"><option value="">No configurar</option><option value="Efecty">Efecty</option></select><div class="field"><label>Cuenta / número / instrucciones</label><input name="datos_pago[]" maxlength="255" placeholder="Número o instrucciones de pago"></div><div class="field"><label>Titular de la cuenta (opcional)</label><input name="titular_pago[]" maxlength="180" placeholder="Nombre del titular"></div></div><div class="card"><label>Zelle</label><select name="metodo_pago[]"><option value="">No configurar</option><option value="Zelle">Zelle</option></select><div class="field"><label>Cuenta / número / instrucciones</label><input name="datos_pago[]" maxlength="255" placeholder="Número o instrucciones de pago"></div><div class="field"><label>Titular de la cuenta (opcional)</label><input name="titular_pago[]" maxlength="180" placeholder="Nombre del titular"></div></div><div class="card"><label>Transferencia bancaria</label><select name="metodo_pago[]"><option value="">No configurar</option><option value="Transferencia bancaria">Transferencia bancaria</option></select><div class="field"><label>Cuenta / número / instrucciones</label><input name="datos_pago[]" maxlength="255" placeholder="Número o instrucciones de pago"></div><div class="field"><label>Titular de la cuenta (opcional)</label><input name="titular_pago[]" maxlength="180" placeholder="Nombre del titular"></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Información profesional</h3><p class="muted">Completa tus datos profesionales para que aparezcan en tu perfil.</p><div class="grid"><div class="field"><label>Matrícula / tarjeta profesional</label><input name="matricula_profesional" required maxlength="120" value="<?php echo cc_srv_h($perfil['matricula_profesional']??''); ?>"></div><div class="field"><label>Años de experiencia</label><input name="experiencia_anos" type="number" min="0" max="70" required value="<?php echo cc_srv_h($perfil['experiencia_anos']??''); ?>"></div><div class="field"><label>Universidad / institución</label><input name="universidad" required maxlength="180" value="<?php echo cc_srv_h($perfil['universidad']??''); ?>"></div></div><div class="field"><label>Especialidades profesionales</label><textarea name="especialidades" required maxlength="3000"><?php echo cc_srv_h($perfil['especialidades']??''); ?></textarea></div><div class="field"><label>Biografía y experiencia relevante</label><textarea name="biografia" required maxlength="5000"><?php echo cc_srv_h($perfil['biografia']??''); ?></textarea></div><div class="field"><label>Referencia del documento de soporte</label><input name="documento_verificacion" maxlength="255" value="<?php echo cc_srv_h($perfil['documento_verificacion']??''); ?>"></div><button class="btn">Enviar datos profesionales y servicio</button></form></section>
<section class="panel" id="contratos"><h2>Contrataciones recibidas</h2><div class="table-wrap"><table><thead><tr><th>Servicio</th><th>Cliente</th><th>Valor</th><th>Estado</th><th>Fecha</th><th>Acción</th></tr></thead><tbody><?php foreach(($data['contrataciones']??[]) as $c): ?><tr><td><?php echo cc_srv_h($c['titulo']); ?></td><td><?php echo cc_srv_h(($c['cliente_nombre']??'').' '.($c['cliente_apellido']??'')); ?></td><td>$<?php echo number_format((float)$c['monto'],0,',','.'); ?> COP</td><td><?php echo cc_srv_h($c['estado_pago']); ?><?php if(!empty($c['referencia_pago_cliente'])): ?><br><small>Pago: <?php echo cc_srv_h($c['metodo_pago_cliente']??''); ?> · Ref: <?php echo cc_srv_h($c['referencia_pago_cliente']); ?><br>Fecha: <?php echo cc_srv_h($c['fecha_pago_cliente']??''); ?> · Banco: <?php echo cc_srv_h($c['banco_origen']??''); ?><?php if(!empty($c['comprobante_url'])): ?><br><a href="<?php echo cc_srv_h($c['comprobante_url']); ?>" target="_blank" rel="noopener noreferrer">Ver comprobante</a><?php endif; ?></small><?php endif; ?></td><td><?php echo cc_srv_h($c['creado_en']); ?></td><td><a class="chat-btn" href="<?php echo URLROOT.'/marketplace/chat/'.(int)$c['id']; ?>">💬 Chat con cliente</a></td></tr><?php endforeach; ?><?php if(empty($data['contrataciones'])): ?><tr><td colspan="6">Todavía no tienes solicitudes.</td></tr><?php endif; ?></tbody></table></div></section>
