<?php endif; ?></main><script>
document.querySelectorAll('.tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===b.dataset.panel));}));
const q=document.getElementById('busqueda'),cat=document.getElementById('especialidad');function filtrar(){document.querySelectorAll('.servicio').forEach(c=>{let t=(c.textContent+' '+c.dataset.search).toLowerCase();c.style.display=(!q.value||t.includes(q.value.toLowerCase()))&&(!cat.value||t.includes(cat.value.toLowerCase()))?'':'none';});}if(q)q.addEventListener('input',filtrar);if(cat)cat.addEventListener('change',filtrar);
</script><script src="<?php echo URLROOT; ?>/public/js/theme.js"></script></body></html>
